INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'The Green Mark uses green leaves surrounding the Earth to convey environmental protection and resource conservation. Certified products meet official standards from the Ministry of Environment, providing clear purchasing guidance.' FROM ui_strings WHERE zh = '環保標章以綠色葉片環繞地球的意象，傳遞守護環境、珍惜資源的理念。取得標章的產品，須符合環境部公告的規格標準並獲得使用證書，讓消費者採購時有清楚的辨識依據。';
INSERT OR IGNORE INTO translations (entity, entity_id, field, lang, value) SELECT 'ui', id, 'text', 'en', 'Green consumerism evolved from global environmental movements. Taiwan introduced its Green Mark system in 1992, encouraging manufacturers to reduce pollution and resource consumption.' FROM ui_strings WHERE zh = '綠色消費的觀念在歐美環保運動中逐漸發展，德國、加拿大、日本與北歐等地也陸續建立環保標章制度。台灣於民國81年推動環保標章，鼓勵製造端減少污染與資源消耗，也讓使用者能支持可回收、低污染與省資源的產品。';
